740	async function provision(job: Job) {
741	  const server = await loadServer(job);
742	  // Clear any stale failure reason from a previous attempt as this run starts, so
743	  // a successful retry doesn't leave the last error hanging around on the row.
744	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null, provisioningStep: null } });
745	  // Best-effort, human-readable "what's happening right now" label for
746	  // <ProvisioningOverlay/> (lib/provisioning-step.ts) — written between the real,
747	  // observable checkpoints below (Proxmox clone/config/start, guest-agent boot,
748	  // SSH reachability, and the game's own port opening). Never allowed to fail
749	  // the provision — it's purely a display aid, same discipline as worker/hosting.ts's
750	  // equivalent `step()`.
751	  const step = (label: string) =>
752	    db.server.update({ where: { id: server.id }, data: { provisioningStep: label } }).catch(() => undefined);
753	
754	  if (SANDBOX) {
755	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
756	    // resize/start, no OVH allocation, no cloud-init snippet write. `vmid` IS
757	    // still allocated for real (via `allocateSandboxVmid`, see its doc comment
758	    // in lib/ipam.ts) — this used to be the racy inline `990000 +
759	    // (await db.server.count())`, which handed two servers the identical vmid
760	    // whenever no other Server row was created between their two provisioning
761	    // runs (the common case: rows are inserted at checkout, well before the
762	    // PROVISION job runs), and the second `prisma.server.update()` below died
763	    // on the `vmid` unique constraint. Only for a fresh allocation — a retry
764	    // keeps whatever vmid a previous attempt already claimed, same rule the
765	    // real Proxmox path follows just below in the non-sandbox branch.
766	    const vmid = server.vmid ?? (await allocateSandboxVmid(server.id));
767	    const password = generatePassword();
768	    const ip = sandboxIp(vmid);
769	    await db.server.update({
770	      where: { id: server.id },
771	      data: { ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
772	    });
773	    await notify(
774	      server.userId,
775	      `Server ${server.hostname} is ready`,
776	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
777	      `/dashboard/servers/${server.id}`
778	    );
779	    // Post-purchase review request (once per server, skipped if no profiles set).
780	    await sendReviewRequestForServer(server.id);
781	    return;
782	  }
783	
784	  const { conn, row: nodeRow } = await nodeFor(server);
785	  const storage = server.plan.storageTier === "hdd"
786	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
787	    : nodeRow?.storageNvme ?? "vmdata";
788	
789	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
790	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
791	  // server's vzdump archives, so the id freed by a deletion comes back carrying
792	  // the old owner's backups — which every backup surface then attributes to the
793	  // new customer (listBackups/requestRestore key on vmid alone). See
794	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
795	  // keeps the vmid already persisted on the row.
796	  // The primary's real backup-archive storage predates the storageHdd naming
797	  // convention (it's literally "backup", not "vmdata-hdd") — every node
798	  // onboarded since names its backup-content storage after storageHdd instead.
799	  // See archivedVmids' doc comment in lib/proxmox.ts for the full story.
800	  const backupStorage = nodeRow?.isPrimary ? "backup" : (nodeRow?.storageHdd ?? "backup");
801	  const vmid = server.vmid ?? (await allocateFreshVmid(conn, backupStorage));
802	
803	  // The password must be generated ONCE per VM, not once per attempt. cloud-init's
804	  // cc_set_passwords module is `frequency: once-per-instance` — it applies whatever
805	  // cipassword was baked into the FIRST boot's snippet and never re-applies on a
806	  // later config change unless the guest gets a brand-new instance-id. A retried
807	  // PROVISION (server.vmid already set = the clone below is skipped as
808	  // `vmAlreadyExists`, so the guest never reboots) used to call generatePassword()
809	  // again anyway and overwrite Server.rootPasswordEnc with a value the running VM
810	  // never saw — every later SSH from the platform (control panel, GAME_POWER,
811	  // mods, backups) then authenticated with a password that does not match
812	  // /etc/shadow on the guest, failing with "All configured authentication methods
813	  // failed" (confirmed live on a real customer server: 2 attempts, 0 accepted
814	  // logins ever, until the guest's password was force-resynced via the QGA
815	  // set-user-password path). Reuse the already-stored password whenever this
816	  // server already has a vmid (meaning some earlier attempt may have already
817	  // cloned + booted it); only a truly first attempt mints a new one.
818	  const password = server.vmid ? (serverRootPassword(server) ?? generatePassword()) : generatePassword();
819	
820	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
821	  // VPS: the global `dedicated_ip_default` setting acts as a platform-wide default (included
822	  // on every plan unless the admin switches it off). Game servers: the customer must
823	  // explicitly purchase the addon at checkout — game orders set `wantsDedicatedIp` from the
824	  // intent, so the global default must NOT override it (that was silently granting free IPs).
825	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
826	  const { getSettingBool: _settingBool } = await import("../lib/settings");
827	  const isGame = !!server.gamePlanId;
828	  const wantDedicated = isGame
829	    ? server.wantsDedicatedIp
830	    : server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
831	  if (wantDedicated && (await dedicatedIpProviderConfigured(nodeRow?.id))) {
832	    try {
833	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
834	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
835	      // nodeRow is THIS server's own node — a Hetzner-hosted server draws from
836	      // the Hetzner pool, not whichever pool happens to be configured (the bug
837	      // this replaces: the old `ovhConfigured()`-only gate had no node
838	      // awareness at all).
839	      dedicated = await allocateDedicatedIp(server.id, vmid, nodeRow?.id);
840	      if (!dedicated) {
841	        // allocateDedicatedIp returns null (not a throw) when the node's pool has
842	        // no FREE customer IP to claim — this used to fall through to NAT with
843	        // zero logging, so a customer could be charged for a dedicated IP addon
844	        // at checkout and silently receive a shared NAT address instead, with no
845	        // error, no failed job, and nothing for anyone to notice. Confirmed live:
846	        // node-2 (Hetzner) had an empty pool (0 rows) and a real customer's
847	        // wantsDedicatedIp order fell back to NAT this way.
848	        console.error(
849	          `[worker] dedicated IP requested for server ${server.id} (node ${nodeRow?.id}) but the pool had no FREE address — falling back to NAT. This customer paid for an IP they did not receive.`,
850	        );
851	      }
852	    } catch (e) {
853	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
854	    }
855	  }
856	  // Node-aware + transactionally-claimed allocation (passing the server id enables
857	  // the claim path, so two concurrent provisions can't pick the same IP/port).
858	  let ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
859	  let sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
860	
861	  try {
862	    await db.server.update({
863	      where: { id: server.id },
864	      data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
865	    });
866	  } catch (e: any) {
867	    // Defense in depth: `Server.ipAddress` is UNIQUE and shared between dedicated
868	    // and NAT addresses, so any future desync between the DedicatedIp pool and
869	    // this column (the class of bug fixed in releaseDedicatedIp — see its
870	    // comment) would otherwise crash-loop identically on every PROVISION retry,
871	    // since cleanupFailedProvision() just re-frees the same stuck pool row. If
872	    // we were the one claiming a dedicated IP, self-heal: null it off whichever
873	    // stale server row is still squatting on it, release our own bad claim, and
874	    // fall back to NAT so this customer's server still deploys.
875	    if (dedicated && e?.code === "P2002") {
876	      console.error(`[worker] dedicated IP ${dedicated.address} collided with a stale Server.ipAddress — self-healing and falling back to NAT`, e);
877	      await db.server.updateMany({ where: { ipAddress: dedicated.address }, data: { ipAddress: null, ipv6: null } });
878	      await releaseDedicatedIp(server.id).catch(() => {});
879	      dedicated = null;
880	      ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
881	      sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
882	      await db.server.update({
883	        where: { id: server.id },
884	        data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
885	      });
886	    } else {
887	      throw e;
888	    }
889	  }
890	
891	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
892	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
893	  // (worker restart mid-clone, or any transient failure in the steps below) would
894	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
895	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
896	  // the clone is idempotent, so skip it when the VM is already present.
897	  let vmAlreadyExists = false;
898	  try {
899	    await conn.vmStatus(vmid);
900	    vmAlreadyExists = true;
901	  } catch {
902	    vmAlreadyExists = false;
903	  }
904	  if (vmAlreadyExists) {
905	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
906	  } else {
907	    await step("Allocating your server…");
908	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
909	      newid: vmid,
910	      name: server.hostname,
911	      full: 1,
912	      storage,
913	    });
914	    await conn.waitForTask(cloneUpid, 600_000);
915	  }
916	
917	  // Per-server cloud-init snippet (base + panel/app install + add-ons).
918	  //
919	  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
920	  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
921	  // failed write hands the VM a vendor-data file that does not exist. Root SSH
922	  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
923	  // all silently vanish, and the customer is still told the server is ready.
924	  // Failing here is recoverable — the job retries, and the clone above is
925	  // idempotent. Continuing is not.
926	  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
927	  // generate its one-time admin password (persisted, once) and get the idempotent
928	  // install script to bake into cloud-init. Null for an ordinary VPS.
929	  (server as any).__nxcloudSetup = await nxcloudSetupForServer(server);
930	  // Live telemetry: mint a fresh per-server shipper token and persist its hash
931	  // BEFORE building cloud-init, so the config the agent boots with matches what
932	  // the ingest route will look up (lib/telemetry-token.ts). Re-provisioning
933	  // (this code path runs again) simply mints a new token, invalidating the old
934	  // one — no rotation UI needed for that case.
935	  (server as any).__telemetryToken = await mintServerTelemetryToken(server.id);
936	
937	  await step("Configuring the network…");
938	  // The vendor snippet must land on THIS SERVER'S OWN NODE's filesystem, but
939	  // there is exactly one worker process for the whole platform and it runs
940	  // only on the primary — it has no local filesystem access to a different
941	  // physical node at all. The primary writes its own snippet directly
942	  // (SNIPPET_DIR); a non-primary node's snippet is written remotely through
943	  // its own node-agent (Phase 3 of the 2026-09-05 multi-node hardening plan —
944	  // see docs/DOCUMENTATION.md's "Multi-node synergy" section) using that
945	  // node's own snippet-capable storage (isPrimary ? "backup" : storageHdd —
946	  // the same divergence fixed for backups the same day). If the agent isn't
947	  // configured yet for that node (no token set, e.g. a node onboarded before
948	  // Phase 3 shipped, or before its agent step was run), this DEGRADES rather
949	  // than hard-fails: native cloud-init (root password + SSH keys below)
950	  // still works fully since it's a Proxmox cfg field, not file-based, so the
951	  // customer gets a normal, SSH-reachable server — just without the vendor
952	  // extras (Claude Code pre-install, Docker/ClamAV add-ons, the game/app
953	  // setup script, MOTD) until the agent is set up for that node. Never
954	  // silently reference a snippet file that was never written — that is the
955	  // exact prior incident this function still guards against for the
956	  // primary's own local write below.
957	  const snippetStorage = nodeRow?.isPrimary ? SNIPPET_STORAGE : (nodeRow?.storageHdd ?? SNIPPET_STORAGE);
958	  const snippetFilename = `nxeon-${vmid}.yaml`;
959	  let cicustom: string | undefined;
960	  if (nodeRow?.isPrimary ?? true) {
961	    const snippet = buildCloudInit(server);
962	    try {
963	      await writeFile(`${SNIPPET_DIR}/${snippetFilename}`, snippet, "utf8");
964	    } catch (e: any) {
965	      throw new Error(
966	        `could not write the cloud-init snippet ${SNIPPET_DIR}/${snippetFilename} (${e?.message ?? e}). ` +
967	          `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
968	          `stopped here rather than reporting a server that would not be usable.`
969	      );
970	    }
971	    cicustom = `vendor=${snippetStorage}:snippets/${snippetFilename}`;
972	  } else if (nodeRow) {
973	    const snippet = buildCloudInit(server);
974	    try {
975	      await agentWriteSnippet(nodeRow, snippetStorage, snippetFilename, snippet);
976	      cicustom = `vendor=${snippetStorage}:snippets/${snippetFilename}`;
977	      console.log(`[worker] wrote a fresh per-VM cloud-init snippet for ${server.id} via node-agent on ${nodeRow.name}`);
978	    } catch (e: any) {
979	      // Correction (found live, same day this degraded path was first built):
980	      // on this fallback, DO NOT delete/override cicustom. `qm clone` already
981	      // copied the TEMPLATE's own cicustom onto this VM, and that static
982	      // "nxeon-vendor.yaml" (scripts/onboard-node.sh step 4, present on every
983	      // onboarded node) is NOT just cosmetic — it sets `ssh_pwauth: true` plus
984	      // a sshd_config drop-in enabling PasswordAuthentication, and `systemctl
985	      // enable --now qemu-guest-agent`. Proxmox's native `cipassword` field
986	      // alone does NOT enable password auth on a stock cloud image (it ships
987	      // with PasswordAuthentication no) — deleting cicustom, as an earlier
988	      // version of this fix did, left the guest with NO way to accept the
989	      // root password at all AND no guest-agent startup, confirmed live by a
990	      // real provision hanging forever on node-2. Leaving cicustom untouched
991	      // means the guest still gets ssh_pwauth + guest-agent from the
992	      // template's own (correctly node-scoped) snippet — just not the per-VM
993	      // extras — whenever the agent call itself fails for any reason.
994	      console.warn(
995	        `[worker] provisioning ${server.id} on non-primary node ${nodeRow.name} — node-agent snippet write ` +
996	          `failed (${e instanceof NodeAgentError ? e.message : String(e?.message ?? e)}), keeping the template's ` +
997	          `static vendor snippet (ssh_pwauth + guest-agent startup) instead; the game/app setup script, Claude ` +
998	          `Code, and other add-ons are skipped for this provision.`
999	      );

