169	/**
170	 * If a GAME OsTemplate's setupScript installs the game via a detached
171	 * `docker run -d --name <container> ...` (true for every game image today —
172	 * see the OsTemplate rows for minecraft/terraria/ark/etc., all `docker run -d`),
173	 * rewrite the invocation to `docker create` and append a generated systemd unit
174	 * that starts/stops the container. Also caps the container's log driver
175	 * (`--log-opt max-size=10m --log-opt max-file=3`) — see the comment at the
176	 * `createCmd` line below for why.
177	 *
178	 * WHY THIS EXISTS: the whole game control panel — GAME_POWER start/stop/restart,
179	 * GAME_BACKUP, log tailing (lib/game-control.ts + worker/game-control.ts) —
180	 * resolves the running game exclusively via `systemctl cat <serviceHint>` /
181	 * `journalctl -u <unit>`. A bare `docker run -d` creates no systemd unit at all,
182	 * so every one of those lookups comes back empty and every control action fails
183	 * silently, on every game family, on every order. Found 2026-08-26 diagnosing a
184	 * customer's Terraria server (cmt9ss7ln000xhlrx0gch9fcx) that could never be
185	 * started/stopped from the dashboard even though PROVISION had completed
186	 * successfully — the container was in fact running, just entirely invisible to
187	 * systemd.
188	 *
189	 * The generated unit is named after the family's FIRST serviceHint, not the
190	 * docker container's own `--name` — the two don't always match (minecraft's
191	 * image runs as container "mc" but its control-spec hints are "minecraft" /
192	 * "minecraft-server") — so `systemctl cat <hint>` resolves regardless of what an
193	 * individual image's setup script happened to call its container.
194	 *
195	 * Intentionally conservative: any setupScript that doesn't match the exact
196	 * `docker run -d --name X ...` shape (or any non-game family, e.g. the
197	 * LAMP/WordPress/Caddy panel images that already install a real native systemd
198	 * service) is returned completely unchanged.
199	 */
200	function wrapDockerGameService(setupScript: string, family: string | null): string {
201	  if (!isGameFamily(family)) return setupScript;
202	  const unitName = controlSpec(family)?.serviceHints[0];
203	  if (!unitName) return setupScript;
204	
205	  const re = /docker run\s+(?:-d|--detach)\b(.*?)\s+--name[= ]("?)([A-Za-z0-9_.-]+)\2(.*)$/.exec(setupScript.trim());
206	  if (!re) return setupScript;
207	  const [full, before, , containerName, after] = re;
208	  const matchIndex = setupScript.indexOf(full);
209	  if (matchIndex < 0) return setupScript;
210	
211	  // Strip docker's own restart policy — systemd now owns restart semantics for
212	  // this container, and leaving both in place makes the two supervisors fight
213	  // over a crash-looping process.
214	  const cleanedAfter = after.replace(/\s*--restart(?:=|\s+)\S+/, "");
215	  // Cap the container's json-file log driver. No game image's setupScript ever
216	  // set this, so a crash-looping container (systemd restarting it every 5s
217	  // forever — see RestartSec above) grows an unbounded log file. Root-caused
218	  // live 2026-09-17 on projectzomboid-kc0kcr: its docker json log alone had
219	  // grown to ~28 GB (on top of ~28.5 GB of rsyslog spamming its own
220	  // "no space left on device" write failures once the disk filled), filling
221	  // the 77 GB root disk to 100% and taking the game server down. This is the
222	  // single construction point every game family's `docker run` is rewritten
223	  // through, so applying the cap here covers all of them at once rather than
224	  // editing each family's setupScript individually. 10m x 3 files = a 30 MB
225	  // ceiling per container regardless of how long or how hard it crash-loops.
226	  const createCmd = `docker create --name ${containerName} --log-opt max-size=10m --log-opt max-file=3${before}${cleanedAfter}`
227	    .replace(/\s+/g, " ")
228	    .trim();
229	
230	  const prefix = setupScript.slice(0, matchIndex);
231	  const unit = [
232	    `cat > /etc/systemd/system/${unitName}.service <<'NXUNIT'`,
233	    "[Unit]",
234	    `Description=Nxeon game service (docker: ${containerName})`,
235	    "After=docker.service",
236	    "Requires=docker.service",
237	    "",
238	    "[Service]",
239	    `ExecStart=/usr/bin/docker start -a ${containerName}`,
240	    `ExecStop=/usr/bin/docker stop -t 30 ${containerName}`,
241	    "Restart=always",
242	    "RestartSec=5",
243	    "TimeoutStartSec=0",
244	    "",
245	    "[Install]",
246	    "WantedBy=multi-user.target",
247	    "NXUNIT",
248	    "systemctl daemon-reload",
249	    `systemctl enable --now ${unitName}`,
250	  ].join("\n");
251	
252	  return `${prefix}${createCmd}\n${unit}`;
253	}
