5	/**
6	 * Host capacity accounting for the deploy flow.
7	 *
8	 * We oversell RAM (the scarce resource) by a factor, but never past the
9	 * host's physical RAM minus a reserve for the hypervisor itself. Disk on
10	 * `vmdata` is large relative to plan sizes, so RAM is the binding constraint.
11	 *
12	 * All values are overridable via env so staging/prod can differ without code
13	 * changes; the defaults match the production KS-GAME box (64 GB RAM).
14	 */
15	export const HOST_RAM_MB = Number(process.env.NXEON_HOST_RAM_MB ?? 64000);
16	export const HOST_RAM_RESERVE_MB = Number(process.env.NXEON_HOST_RAM_RESERVE_MB ?? 8000);
17	export const RAM_OVERSELL_FACTOR = Number(process.env.NXEON_RAM_OVERSELL ?? 1.5);
18	
19	/**
20	 * Usable NVMe VM-disk pool in GB, used as a fallback when the live Proxmox
21	 * storage total can't be read. Unlike RAM we do NOT oversell disk — thin
22	 * provisioning already lets guests share the pool, so we commit against the
23	 * real pool size minus a safety margin.
24	 */
25	export const HOST_DISK_GB = Number(process.env.NXEON_HOST_DISK_GB ?? 800);
26	/** Fraction of usable disk we allow to be committed before refusing deploys. */
27	export const DISK_SAFETY_RATIO = Number(process.env.NXEON_DISK_SAFETY ?? 0.9);
28	/**
29	 * VM disk on ZFS is THIN-provisioned: a guest only consumes what it actually
30	 * writes, not its full nominal plan size. So committing raw plan sizes against
31	 * the pool wildly under-counts real capacity (e.g. four ~2 GB-used guests read
32	 * as 275 GB "committed"). We therefore oversell nominal disk like RAM, and rely
33	 * on the live free-space floor below as the true overflow guard.
34	 */
35	export const DISK_OVERSELL_FACTOR = Number(process.env.NXEON_DISK_OVERSELL ?? 3);
36	/** Refuse deploys once the pool's REAL free space would sit below this (GB). */
37	export const DISK_MIN_FREE_GB = Number(process.env.NXEON_DISK_MIN_FREE_GB ?? 20);
38	
39	/** Effective committable RAM ceiling in MB after reserve + oversell. */
40	export function ramCeilingMB(): number {
41	  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
42	}
