44	export type CapacitySnapshot = {
45	  committedRamMB: number;
46	  committedDiskGB: number;
47	  ceilingRamMB: number;
48	  serverCount: number;
49	  /** 0..1 fraction of the RAM ceiling already committed. */
50	  ramUtilization: number;
51	  /** true once committed RAM is within 15% of the ceiling. */
52	  nearCapacity: boolean;
53	};
