55	/** Sum committed RAM/disk across all servers that are not being torn down. */
56	export async function capacitySnapshot(): Promise<CapacitySnapshot> {
57	  const servers = await db.server.findMany({
58	    where: { status: { not: "DELETING" } },
59	    select: {
60	      extraDiskGB: true,
61	      plan: { select: { ramMB: true, diskGB: true } },
62	      gamePlan: { select: { ramMB: true, diskGB: true } },
63	    },
64	  });
65	  // A game server's real commitment is its game plan's, not the (larger)
66	  // base VPS plan it rides on — overstating this made the platform think it
67	  // had less real capacity than it did.
68	  const committedRamMB = servers.reduce((sum, s) => sum + (s.gamePlan?.ramMB ?? s.plan.ramMB), 0);
69	  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(baseDiskGBFor(s), s.extraDiskGB), 0);
70	  const ceilingRamMB = ramCeilingMB();
71	  const ramUtilization = ceilingRamMB > 0 ? committedRamMB / ceilingRamMB : 1;
72	  return {
73	    committedRamMB,
74	    committedDiskGB,
75	    ceilingRamMB,
76	    serverCount: servers.length,
77	    ramUtilization,
78	    nearCapacity: ramUtilization >= 0.85,
79	  };
80	}
