82	/**
83	 * Pure boundary check, split out of `capacityCheckRamMB` so it can be unit-tested
84	 * with no DB (see test/custom-plan-capacity.test.ts): would adding `addRamMB` to
85	 * what's already committed push past the ceiling?
86	 */
87	export function ramProjectionExceedsCeiling(committedRamMB: number, ceilingRamMB: number, addRamMB: number): boolean {
88	  return committedRamMB + addRamMB > ceilingRamMB;
89	}
