91	/**
92	 * Would committing `ramMB` more push committed RAM past the oversell ceiling?
93	 * Returns { ok:false, reason } when the host cannot take it.
94	 *
95	 * Factored out of `capacityCheck` so a caller that doesn't have (or want) a
96	 * `Plan` row — a CUSTOM spec, which by definition doesn't match any catalog
97	 * plan — gets the exact same oversell guard a premade-plan order gets, instead
98	 * of a second, drifting copy of this math. See lib/custom-plan.ts.
99	 *
100	 * Fleet-aware: this used to sum committed RAM across EVERY server (regardless
101	 * of node) against ONE flat env-configured ceiling — correct with a single
102	 * node, but wrong the moment a second node exists: it would refuse a valid
103	 * order the instant the FLEET's total commitment passed one node's worth of
104	 * capacity, even while the other node sat nearly empty (the opposite of what
105	 * adding a node is for). `scheduleNode()` (lib/node-capacity.ts) already
106	 * bin-packs the actual placement across nodes, so this gate asks the same
107	 * question: is there room on ANY enabled, online node? A server with no
108	 * `nodeId` (legacy game-server orders, before per-order scheduling existed)
109	 * is attributed to the primary node, matching `worker/index.ts`'s own
110	 * `nodeFor()` fallback — otherwise the primary's real load would be
111	 * undercounted here.
112	 */
113	export async function capacityCheckRamMB(ramMB: number): Promise<{ ok: boolean; reason?: string }> {
114	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
115	  if (nodes.length === 0) {
116	    // No Node rows configured — fall back to the original flat, env-configured
117	    // single-host ceiling (matches pre-multi-node behavior/tests).
118	    const snap = await capacitySnapshot();
119	    if (ramProjectionExceedsCeiling(snap.committedRamMB, snap.ceilingRamMB, ramMB)) {
120	      return {
121	        ok: false,
122	        reason:
123	          "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
124	          "Please try a smaller plan or contact support.",
125	      };
126	    }
127	    return { ok: true };
128	  }
129	
130	  const primary = nodes.find((n) => n.isPrimary) ?? nodes[0];
131	  const loads = await Promise.all(
132	    nodes.map(async (n) => {
133	      const servers = await db.server.findMany({
134	        where: {
135	          status: { not: "DELETING" },
136	          OR: n.id === primary.id ? [{ nodeId: n.id }, { nodeId: null }] : [{ nodeId: n.id }],
137	        },
138	        select: { plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
139	      });
140	      const committed = servers.reduce((sum, s) => sum + (s.gamePlan?.ramMB ?? s.plan.ramMB), 0);
141	      const ceiling = n.capacityRamMB * RAM_OVERSELL_FACTOR;
142	      return { committed, ceiling };
143	    })
144	  );
145	
146	  const hasRoom = loads.some((l) => !ramProjectionExceedsCeiling(l.committed, l.ceiling, ramMB));
147	  if (!hasRoom) {
148	    return {
149	      ok: false,
150	      reason:
151	        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
152	        "Please try a smaller plan or contact support.",
153	    };
154	  }
155	  return { ok: true };
156	}
